//! Renderers for the three generated manifest files, plus the closed
//! additional-proof row builder.

use crate::data::{
    ADDITIONAL_PROOF_SPECS, BLOCK_TO_MECHANISM, BLOCK_TO_ORGAN, BLOCK_TO_UBLOCK,
    BLOCK_VERIFICATION_LABELS, FILE_TO_SUBSTRATE,
};
use crate::derive::{
    block_prereqs, block_required_guards, consumed_mechs_for_block, keys_for_row,
    lookup_pair_or_fail, mechanism_for_row,
};
use crate::model::Row;

/// Verbatim header emitted at the top of every generated file. The header
/// text is part of the byte-pinned generated artifact contract
/// (`typeinfo_manifest_files_are_byte_equal_to_regenerated_generator_output`)
/// and is therefore preserved byte-for-byte.
const GENERATED_HEADER: &str = concat!(
    "// Auto-generated by the `gen-typeinfo-manifest` cargo bin\n",
    "// (`pnpm gen:typeinfo-manifest`). DO NOT hand-edit. The §10.4.1\n",
    "// row->block partition in `docs/arch/native-typeinfo-parity.md`\n",
    "// is the authoritative source ONLY for each IgnoredTestRow's\n",
    "// `block_id` (READ by the generator, joined with the live\n",
    "// `#[ignore]` discovery + the Capability Map). This includes LIFTED\n",
    "// rows: their `block_id` comes from §10.4.1 too — there is NO\n",
    "// generator-side block override. The AdditionalProofRow\n",
    "// table and the TYPEINFO_PARITY_BLOCKS DAG (each block's\n",
    "// required_guards/verification_labels/prereqs/mechanisms) are\n",
    "// authored in the generator's own static Rust maps, NOT in §10.4.1.\n",
    "// The Rust guards only diff/fail; they never write this file.\n",
);

fn joined_query_names(keys: &[&str]) -> String {
    keys.iter()
        .map(|k| format!("SemanticQueryName::{k}"))
        .collect::<Vec<_>>()
        .join(", ")
}

fn joined_mechanism_ids(mechs: &[&str]) -> String {
    mechs
        .iter()
        .map(|m| format!("MechanismId::{m}"))
        .collect::<Vec<_>>()
        .join(", ")
}

pub(crate) fn emit_ignored_rows(rows: &[Row]) -> String {
    let mut out: Vec<String> = vec![
        GENERATED_HEADER.to_string(),
        String::new(),
        "#[rustfmt::skip]".to_string(),
        "const EXPECTED_IGNORE_MANIFEST: &[IgnoredTestRow] = &[".to_string(),
    ];
    for r in rows {
        let keys = joined_query_names(&r.keys);
        let mechs = joined_mechanism_ids(&r.consumed);
        out.push(format!(
            "    IgnoredTestRow {{ \
             file: \"{file}\", \
             function: \"{func}\", \
             substrate: TargetSubstrate::{substrate}, \
             capability: TypeInfoCapability::{cap}, \
             organ: ArchitectureOrgan::{organ}, \
             owning_u_block: UBlock::{ublock}, \
             block_id: TypeInfoParityBlockId::{block}, \
             semantic_queries: &[{keys}], \
             proof: {proof}, \
             status: {status}, \
             oracle_query_ordinals: {ordinals}, \
             mechanism_id: MechanismId::{mech}, \
             consumed_mechanisms: &[{mechs}], \
             unblocker: \"{unblocker}\" }},",
            file = r.file,
            func = r.func,
            substrate = r.substrate,
            cap = r.cap,
            organ = r.organ,
            ublock = r.ublock,
            block = r.block,
            proof = r.proof,
            status = r.status,
            ordinals = r.oracle_query_ordinals,
            mech = r.mech,
            unblocker = r.unblocker,
        ));
    }
    out.push("];".to_string());
    out.join("\n") + "\n"
}

pub(crate) fn emit_additional_rows(rows: &[Row]) -> String {
    let mut out: Vec<String> = vec![
        GENERATED_HEADER.to_string(),
        String::new(),
        "#[rustfmt::skip]".to_string(),
        "const ADDITIONAL_PROOF_ROWS: &[AdditionalProofRow] = &[".to_string(),
    ];
    for r in rows {
        let keys = joined_query_names(&r.keys);
        let mechs = joined_mechanism_ids(&r.consumed);
        out.push(format!(
            "    AdditionalProofRow {{ \
             file: \"{file}\", \
             function: \"{func}\", \
             substrate: TargetSubstrate::{substrate}, \
             capability: TypeInfoCapability::{cap}, \
             organ: ArchitectureOrgan::{organ}, \
             owning_u_block: UBlock::{ublock}, \
             block_id: TypeInfoParityBlockId::{block}, \
             semantic_queries: &[{keys}], \
             proof: {proof}, \
             mechanism_id: MechanismId::{mech}, \
             consumed_mechanisms: &[{mechs}] }},",
            file = r.file,
            func = r.func,
            substrate = r.substrate,
            cap = r.cap,
            organ = r.organ,
            ublock = r.ublock,
            block = r.block,
            proof = r.proof,
            mech = r.mech,
        ));
    }
    out.push("];".to_string());
    out.join("\n") + "\n"
}

pub(crate) fn emit_block_rows() -> String {
    let mut out: Vec<String> = vec![
        GENERATED_HEADER.to_string(),
        String::new(),
        "#[rustfmt::skip]".to_string(),
        "const TYPEINFO_PARITY_BLOCKS: &[BlockContractRow] = &[".to_string(),
    ];
    let verification = BLOCK_VERIFICATION_LABELS
        .iter()
        .map(|label| format!("\"{label}\""))
        .collect::<Vec<_>>()
        .join(", ");
    for &(block, mechanism) in BLOCK_TO_MECHANISM {
        let prereqs = block_prereqs(block)
            .iter()
            .map(|p| format!("TypeInfoParityBlockId::{p}"))
            .collect::<Vec<_>>()
            .join(", ");
        let consumed = joined_mechanism_ids(&consumed_mechs_for_block(block));
        let guards = block_required_guards(block)
            .iter()
            .map(|g| format!("\"{g}\""))
            .collect::<Vec<_>>()
            .join(", ");
        out.push(format!(
            "    BlockContractRow {{ \
             block_id: TypeInfoParityBlockId::{block}, \
             owning_u_block: UBlock::{ublock}, \
             organ: ArchitectureOrgan::{organ}, \
             prereqs: &[{prereqs}], \
             mechanism_id: MechanismId::{mechanism}, \
             consumed_mechanisms: &[{consumed}], \
             required_guards: &[{guards}], \
             verification_labels: &[{verification}] }},",
            ublock = lookup_pair_or_fail(BLOCK_TO_UBLOCK, block, "BLOCK_TO_UBLOCK"),
            organ = lookup_pair_or_fail(BLOCK_TO_ORGAN, block, "BLOCK_TO_ORGAN"),
        ));
    }
    out.push("];".to_string());
    out.join("\n") + "\n"
}

/// The CLOSED set of 7 `AdditionalProofRow`s (§8 + §10.1), projected from
/// the shared `ADDITIONAL_PROOF_SPECS` table (the same table
/// `validate::additional_proof_mechanism_consumers` models from). All 7
/// rows are FORWARD-DECLARATION coverage contracts emitting a RowTestGuard:
/// the 6 JSX no-new-key submatrix rows point at the U2.JSX_FOUNDATIONS test
/// functions, and the 1 mapped companion points at the U2.MAPPED_TEMPLATE
/// test function.
pub(crate) fn build_additional_rows() -> Vec<Row> {
    ADDITIONAL_PROOF_SPECS
        .iter()
        .map(|spec| {
            let mech = mechanism_for_row(spec.capability, spec.file, spec.func);
            Row {
                file: spec.file.to_string(),
                func: spec.func.to_string(),
                substrate: lookup_pair_or_fail(FILE_TO_SUBSTRATE, spec.file, "FILE_TO_SUBSTRATE"),
                cap: spec.capability.to_string(),
                organ: lookup_pair_or_fail(BLOCK_TO_ORGAN, spec.block, "BLOCK_TO_ORGAN"),
                ublock: lookup_pair_or_fail(BLOCK_TO_UBLOCK, spec.block, "BLOCK_TO_UBLOCK"),
                block: spec.block,
                keys: keys_for_row(mech).to_vec(),
                proof: format!(
                    "ProofRequirement::RowTestGuard {{ file: \"{file}\", \
                     function: \"{func}\" }}",
                    file = spec.file,
                    func = spec.func,
                ),
                mech,
                consumed: consumed_mechs_for_block(spec.block),
                status: String::new(),
                oracle_query_ordinals: 0,
                unblocker: String::new(),
            }
        })
        .collect()
}
